t.script:
pdfjsLib.GlobalWorkerOptions.workerSrc =
    'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';

var DOC_URL     = window.ES_DOC_URL;
var TOKEN       = window.ES_TOKEN;
var FIELDS_DATA = window.ES_FIELDS_DATA;

var pages = [];   // { pageEl, canvas, renderedW, renderedH, pageNum }
var fieldValues = {};  // templateFieldId → { value, signatureDataUrl }
var totalRequired = 0;
var currentModalFieldId = null;
var modalCanvas = null, modalCtx = null, modalDrawing = false;

// ─── Render PDF with pdfjs ───────────────────────────────
async function renderSigningPDF() {
    var pdf = await pdfjsLib.getDocument(DOC_URL).promise;
    document.getElementById('pdfLoading').remove();
    var area = document.getElementById('pdfJsArea');

    for (var p = 1; p <= pdf.numPages; p++) {
        var page = await pdf.getPage(p);
        var viewport = page.getViewport({ scale: 1.3 });

        var pageEl = document.createElement('div');
        pageEl.className = 'es-pdfjs-page';
        pageEl.dataset.pageNum = p;
        pageEl.style.width = viewport.width + 'px';
        pageEl.style.height = viewport.height + 'px';
        pageEl.style.position = 'relative';

        var canvas = document.createElement('canvas');
        canvas.width  = viewport.width;
        canvas.height = viewport.height;
        pageEl.appendChild(canvas);
        area.appendChild(pageEl);

        pages.push({ pageEl, canvas, renderedW: viewport.width, renderedH: viewport.height, pageNum: p });
    }

    // Place field overlays instantly before rendering canvas pixels
    placeFieldOverlays();

    // Lazy load the actual canvas rendering
    var observer = new IntersectionObserver(function(entries) {
        entries.forEach(function(entry) {
            if (entry.isIntersecting) {
                var pNum = parseInt(entry.target.dataset.pageNum);
                observer.unobserve(entry.target);
                pdf.getPage(pNum).then(function(page) {
                    var viewport = page.getViewport({ scale: 1.3 });
                    var ctx = entry.target.querySelector('canvas').getContext('2d');
                    page.render({ canvasContext: ctx, viewport: viewport });
                });
            }
        });
    }, { root: area, rootMargin: '800px' });

    document.querySelectorAll('.es-pdfjs-page').forEach(function(el) {
        observer.observe(el);
    });
}

// ─── Place field overlays ────────────────────────────────
function placeFieldOverlays() {
    totalRequired = 0;
    FIELDS_DATA.forEach(function(fd) {
        if (fd.required) totalRequired++;
        var pg = pages.find(function(p) { return p.pageNum === fd.page; });
        if (!pg) return;

        var pw = pg.renderedW, ph = pg.renderedH;
        var ov = document.createElement('div');
        ov.className = 'es-field-sign-overlay type-' + fd.field_type;
        ov.dataset.fid = fd.id;
        ov.style.left   = (fd.pos_x / 100 * pw) + 'px';
        ov.style.top    = (fd.pos_y / 100 * ph) + 'px';
        ov.style.width  = (fd.width  / 100 * pw) + 'px';
        ov.style.height = (fd.height / 100 * ph) + 'px';
        ov.style.position = 'absolute';

        buildOverlayContent(ov, fd, pw, ph);

        pg.pageEl.style.position = 'relative';
        pg.pageEl.appendChild(ov);
    });
    updateProgress();
}

function buildOverlayContent(ov, fd, pw, ph) {
    if (fd.field_type === 'signature' || fd.field_type === 'initial') {
        // Click to open modal signature pad
        var ph_label = document.createElement('div');
        ph_label.className = 'fov-placeholder';
        ph_label.textContent = fd.placeholder || (fd.field_type === 'signature' ? '✍️ Click to Sign' : '✍️ Click to Initial');
        ov.appendChild(ph_label);

        var clr = document.createElement('span');
        clr.className = 'fov-clear'; clr.textContent = '✕';
        clr.onclick = function(e) { e.stopPropagation(); clearField(fd.id, ov, ph_label); };
        ov.appendChild(clr);

        ov.onclick = function() { openSignatureModal(fd.id, ov, ph_label); };

    } else if (fd.field_type === 'checkbox') {
        var chk = document.createElement('input');
        chk.type = 'checkbox';
        chk.style.cssText = 'width:60%;height:60%;cursor:pointer;position:relative;';
        chk.onchange = function() {
            fieldValues[fd.id] = { value: chk.checked ? 'true' : '', signatureDataUrl: '' };
            ov.classList.toggle('filled', chk.checked);
            updateProgress();
        };
        ov.style.justifyContent = 'center';
        ov.appendChild(chk);

    } else {
        // Text-based: name, date, email, text
        var inp = document.createElement('input');
        inp.type = fd.field_type === 'date' ? 'date' : 'text';
        inp.placeholder = fd.placeholder || fd.field_type;
        inp.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;border:none;background:transparent;padding:2px 6px;font-size:12px;color:#1e293b;';
        inp.oninput = function() {
            fieldValues[fd.id] = { value: inp.value, signatureDataUrl: '' };
            ov.classList.toggle('filled', !!inp.value);
            updateProgress();
        };
        ov.appendChild(inp);
    }

    // Pre-fill if existing value
    if (fd.value) {
        fieldValues[fd.id] = { value: fd.value, signatureDataUrl: '' };
        ov.classList.add('filled');
        var inp2 = ov.querySelector('input');
        if (inp2 && inp2.type !== 'checkbox') inp2.value = fd.value;
    }
}

// ─── Modal signature pad ─────────────────────────────────
function openSignatureModal(fieldId, ov, phLabel) {
    currentModalFieldId = fieldId;
    var modal = document.getElementById('sigModal');
    modal.style.display = 'flex';
    modalCanvas = document.getElementById('modalSigCanvas');
    modalCtx = modalCanvas.getContext('2d');
    clearModalCanvas();
    modalCanvas.onmousedown  = startDraw;
    modalCanvas.onmousemove  = draw;
    modalCanvas.onmouseup    = stopDraw;
    modalCanvas.onmouseleave = stopDraw;
    modalCanvas.ontouchstart = function(e) { e.preventDefault(); startDraw(e.touches[0]); };
    modalCanvas.ontouchmove  = function(e) { e.preventDefault(); draw(e.touches[0]); };
    modalCanvas.ontouchend   = stopDraw;
    modal._ov = ov; modal._phLabel = phLabel;
}

function startDraw(e) {
    modalDrawing = true;
    var r = modalCanvas.getBoundingClientRect();
    modalCtx.beginPath();
    modalCtx.moveTo(e.clientX - r.left, e.clientY - r.top);
}
function draw(e) {
    if (!modalDrawing) return;
    var r = modalCanvas.getBoundingClientRect();
    var scaleX = modalCanvas.width / r.width;
    var scaleY = modalCanvas.height / r.height;
    modalCtx.lineTo((e.clientX - r.left) * scaleX, (e.clientY - r.top) * scaleY);
    modalCtx.strokeStyle = '#1e293b'; modalCtx.lineWidth = 2;
    modalCtx.lineCap = 'round'; modalCtx.stroke();
}
function stopDraw() { modalDrawing = false; }
function clearModalCanvas() { if (modalCtx) modalCtx.clearRect(0, 0, modalCanvas.width, modalCanvas.height); }

function closeModal(apply) {
    var modal = document.getElementById('sigModal');
    if (apply && currentModalFieldId !== null) {
        var dataUrl = modalCanvas.toDataURL('image/png');
        var ov = modal._ov;
        var phLabel = modal._phLabel;
        // Show the drawn signature in the overlay
        ov.querySelectorAll('.sig-preview').forEach(function(el) { el.remove(); });
        var img = document.createElement('img');
        img.className = 'sig-preview';
        img.src = dataUrl;
        img.style.cssText = 'position:absolute;inset:2px;width:calc(100% - 4px);height:calc(100% - 4px);object-fit:contain;pointer-events:none;';
        ov.appendChild(img);
        if (phLabel) phLabel.style.display = 'none';
        ov.classList.add('filled');
        fieldValues[currentModalFieldId] = { value: '', signatureDataUrl: dataUrl };
        updateProgress();
    }
    modal.style.display = 'none';
}

function clearField(fieldId, ov, phLabel) {
    delete fieldValues[fieldId];
    ov.classList.remove('filled');
    ov.querySelectorAll('.sig-preview').forEach(function(el) { el.remove(); });
    if (phLabel) phLabel.style.display = '';
    updateProgress();
}

// ─── Progress ────────────────────────────────────────────
function updateProgress() {
    var filled = FIELDS_DATA.filter(function(fd) {
        return fd.required ? !!fieldValues[fd.id] : true;
    }).length;
    var total = FIELDS_DATA.filter(function(fd) { return fd.required; }).length;
    var allFilled = FIELDS_DATA.filter(function(fd) { return fd.required; }).every(function(fd) {
        var fv = fieldValues[fd.id];
        return fv && (fv.value || fv.signatureDataUrl);
    });
    document.getElementById('progressLabel').textContent =
        Object.keys(fieldValues).length + ' of ' + total + ' required fields filled';
    var pct = total > 0 ? Math.round(Object.keys(fieldValues).filter(function(k) {
        var fv = fieldValues[k];
        return fv && (fv.value || fv.signatureDataUrl);
    }).length / total * 100) : 0;
    document.getElementById('progressBar').style.width = Math.min(100, pct) + '%';
}

// ─── Submit ──────────────────────────────────────────────
document.getElementById('btnSign').addEventListener('click', async function() {
    // Validate required fields
    var missing = FIELDS_DATA.filter(function(fd) {
        if (!fd.required) return false;
        var fv = fieldValues[fd.id];
        return !fv || (!fv.value && !fv.signatureDataUrl);
    });
    if (missing.length > 0) {
        showError('Please fill all required fields: ' + missing.map(function(f) {
            return f.placeholder || f.field_type;
        }).join(', '));
        return;
    }

    document.getElementById('btnSignText').classList.add('d-none');
    document.getElementById('btnSignSpinner').classList.remove('d-none');
    this.disabled = true;

    var formData = new FormData();
    FIELDS_DATA.forEach(function(fd) {
        var fv = fieldValues[fd.id];
        if (fv) {
            formData.append('field_' + fd.id + '_value', fv.value || '');
            formData.append('field_' + fd.id + '_signature', fv.signatureDataUrl || '');
        }
    });

    try {
        var resp = await fetch('/sign/submit/' + TOKEN, { method: 'POST', body: formData });
        var data = await resp.json();
        if (data.success) {
            document.getElementById('btnSign').classList.add('d-none');
            document.getElementById('msgSuccess').classList.remove('d-none');
            setTimeout(function() { location.reload(); }, 2000);
        } else {
            showError(data.error || 'Submission failed.');
            resetBtn();
        }
    } catch (e) {
        showError('Network error: ' + e.message);
        resetBtn();
    }
});

function resetBtn() {
    var btn = document.getElementById('btnSign');
    btn.disabled = false;
    document.getElementById('btnSignText').classList.remove('d-none');
    document.getElementById('btnSignSpinner').classList.add('d-none');
}
function showError(msg) {
    var el = document.getElementById('msgError');
    document.getElementById('msgErrorText').textContent = msg;
    el.classList.remove('d-none');
}

// Init
renderSigningPDF();

body.script:
// ── Language Switch ──────────────────────────────────────
var esCurrentLang = localStorage.getItem('es_lang') || 'en';
function esApplyLang(lang) {
    var root = document.getElementById('esRoot');
    var label = document.getElementById('esLangLabel');
    if (lang === 'ar') { root.setAttribute('dir','rtl'); root.setAttribute('lang','ar'); label.textContent='English'; }
    else { root.setAttribute('dir','ltr'); root.setAttribute('lang','en'); label.textContent='عربي'; }
    document.querySelectorAll('.es-i18n').forEach(function(el) {
        var txt = el.getAttribute('data-' + lang);
        if (txt) el.textContent = txt;
    });
    localStorage.setItem('es_lang', lang);
    esCurrentLang = lang;
}
function esToggleLang() { esApplyLang(esCurrentLang === 'en' ? 'ar' : 'en'); }
document.addEventListener('DOMContentLoaded', function() { esApplyLang(esCurrentLang); });

